      ],
      "curriculumType": "semester",
      "curriculum": [
        {
          "year": "First Year",
          "semesters": [
            {
              "semester": 1,
              "subjects": [
                {
                  "name": "MTIO 101: Operating System & Real Time OS",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Covers&nbsp;fundamental&nbsp;operating-system&nbsp;concepts&nbsp;and&nbsp;real-time&nbsp;operating&nbsp;systems,&nbsp;with&nbsp;emphasis&nbsp;on&nbsp;process&nbsp;management,&nbsp;scheduling,&nbsp;memory&nbsp;management,&nbsp;and&nbsp;real-time&nbsp;system&nbsp;requirements&nbsp;relevant&nbsp;to&nbsp;IoT&nbsp;applications.</span></p>",
                  "group": ""
                },
                {
                  "name": "MTIO 102: Embedded System and Microcontrollers",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Introduces&nbsp;embedded-system&nbsp;architecture,&nbsp;microcontrollers,&nbsp;interfacing,&nbsp;programming,&nbsp;and&nbsp;hardware–software&nbsp;integration.&nbsp;The&nbsp;subject&nbsp;develops&nbsp;the&nbsp;foundation&nbsp;required&nbsp;for&nbsp;designing&nbsp;IoT-enabled&nbsp;embedded&nbsp;devices.</span></p>"
                },
