                },
                {
                  "name": "MTIO 104: Advance Computer Networks",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Covers&nbsp;advanced&nbsp;concepts&nbsp;in&nbsp;computer&nbsp;networking,&nbsp;communication&nbsp;protocols,&nbsp;network&nbsp;architecture,&nbsp;and&nbsp;data&nbsp;transmission.&nbsp;It&nbsp;develops&nbsp;the&nbsp;networking&nbsp;foundation&nbsp;required&nbsp;for&nbsp;communication&nbsp;and&nbsp;connectivity&nbsp;among&nbsp;IoT&nbsp;devices.</span></p>"
                },
                {
                  "name": "MTIO 105: Elective-I",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">An&nbsp;elective&nbsp;course&nbsp;allowing&nbsp;students&nbsp;to&nbsp;specialize&nbsp;in&nbsp;an&nbsp;area&nbsp;complementary&nbsp;to&nbsp;IoT.&nbsp;Students&nbsp;can&nbsp;choose&nbsp;</span><strong style=\"color: rgb(0, 0, 0);\">Software&nbsp;Engineering,&nbsp;Database&nbsp;Management&nbsp;System,&nbsp;or&nbsp;Advance&nbsp;Distributed&nbsp;Systems</strong><span style=\"color: rgb(0, 0, 0);\">.</span></p>"
                },
                {
                  "name": "MTIO 106: Lab-I (101 and 102)",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Provides&nbsp;practical&nbsp;exposure&nbsp;to&nbsp;</span><strong style=\"color: rgb(0, 0, 0);\">Operating&nbsp;System&nbsp;&amp;&nbsp;Real&nbsp;Time&nbsp;OS</strong><span style=\"color: rgb(0, 0, 0);\">&nbsp;and&nbsp;</span><strong style=\"color: rgb(0, 0, 0);\">Embedded&nbsp;System&nbsp;and&nbsp;Microcontrollers</strong><span style=\"color: rgb(0, 0, 0);\">,&nbsp;enabling&nbsp;students&nbsp;to&nbsp;implement&nbsp;and&nbsp;experimentally&nbsp;understand&nbsp;concepts&nbsp;related&nbsp;to&nbsp;embedded&nbsp;and&nbsp;real-time&nbsp;IoT&nbsp;system</span></p>"
                },
                {
                  "name": "MTIO 107: Lab-II (103 and 104)",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Provides&nbsp;hands-on&nbsp;experience&nbsp;with&nbsp;</span><strong style=\"color: rgb(0, 0, 0);\">Sensors&nbsp;and&nbsp;Signal&nbsp;Conditioning</strong><span style=\"color: rgb(0, 0, 0);\">&nbsp;and&nbsp;</span><strong style=\"color: rgb(0, 0, 0);\">Advanced&nbsp;Computer&nbsp;Networks</strong><span style=\"color: rgb(0, 0, 0);\">,&nbsp;focusing&nbsp;on&nbsp;sensor&nbsp;interfacing,&nbsp;signal&nbsp;acquisition,&nbsp;communication,&nbsp;and&nbsp;networking&nbsp;concepts&nbsp;used&nbsp;in&nbsp;IoT</span></p>"
                }
              ]
            },
            {
              "semester": 2,
              "subjects": [
                {
                  "name": "MTIO 201: IoT Architecture and Protocols",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Covers&nbsp;the&nbsp;fundamental&nbsp;architecture&nbsp;of&nbsp;IoT&nbsp;systems&nbsp;and&nbsp;the&nbsp;communication&nbsp;protocols&nbsp;used&nbsp;for&nbsp;device&nbsp;connectivity&nbsp;and&nbsp;data&nbsp;exchange.&nbsp;It&nbsp;provides&nbsp;an&nbsp;understanding&nbsp;of&nbsp;layered&nbsp;IoT&nbsp;architectures&nbsp;and&nbsp;protocols&nbsp;supporting&nbsp;heterogeneous&nbsp;IoT&nbsp;devices.</span></p>"
                },
                {
                  "name": "MTIO 202: Security in IoT",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Introduces&nbsp;security&nbsp;challenges&nbsp;and&nbsp;requirements&nbsp;in&nbsp;IoT&nbsp;environments,&nbsp;including&nbsp;protection&nbsp;of&nbsp;devices,&nbsp;networks,&nbsp;communication,&nbsp;and&nbsp;data.&nbsp;The&nbsp;subject&nbsp;focuses&nbsp;on&nbsp;security&nbsp;mechanisms&nbsp;and&nbsp;approaches&nbsp;for&nbsp;developing&nbsp;secure&nbsp;IoT&nbsp;systems.</span></p>"
                },
                {
                  "name": "MTIO 203: Wireless Sensor Networks",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Covers&nbsp;the&nbsp;principles,&nbsp;architecture,&nbsp;communication,&nbsp;and&nbsp;operation&nbsp;of&nbsp;wireless&nbsp;sensor&nbsp;networks.&nbsp;It&nbsp;develops&nbsp;an&nbsp;understanding&nbsp;of&nbsp;sensor-node&nbsp;communication&nbsp;and&nbsp;network&nbsp;organization&nbsp;for&nbsp;distributed&nbsp;sensing&nbsp;and&nbsp;IoT&nbsp;applications.</span></p>"
                },
                {
                  "name": "MTIO 204: Elective-II",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Provides&nbsp;an&nbsp;opportunity&nbsp;to&nbsp;develop&nbsp;specialized&nbsp;knowledge&nbsp;in&nbsp;an&nbsp;area&nbsp;related&nbsp;to&nbsp;IoT.&nbsp;Students&nbsp;can&nbsp;choose&nbsp;</span><strong style=\"color: rgb(0, 0, 0);\">Mobile&nbsp;Application&nbsp;Development,&nbsp;Blockchain&nbsp;Technology,&nbsp;or&nbsp;Cloud&nbsp;and&nbsp;Fog&nbsp;Computing</strong><span style=\"color: rgb(0, 0, 0);\">.</span></p>"
                },
                {
                  "name": "MTIO 205: Elective-III",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Enables&nbsp;students&nbsp;to&nbsp;specialize&nbsp;in&nbsp;advanced&nbsp;technologies&nbsp;supporting&nbsp;IoT&nbsp;data&nbsp;processing,&nbsp;programming,&nbsp;and&nbsp;networking.&nbsp;The&nbsp;available&nbsp;choices&nbsp;are&nbsp;</span><strong style=\"color: rgb(0, 0, 0);\">Python&nbsp;for&nbsp;IoT,&nbsp;Big&nbsp;Data&nbsp;Analytics&nbsp;for&nbsp;IoT,&nbsp;or&nbsp;SDN&nbsp;and&nbsp;NFV&nbsp;for&nbsp;IoT</strong><span style=\"color: rgb(0, 0, 0);\">.</span></p>"
                },
                {
                  "name": "MTIO 206: Lab-III (201 and 202)",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Provides&nbsp;practical&nbsp;implementation&nbsp;of&nbsp;concepts&nbsp;covered&nbsp;in&nbsp;</span><strong style=\"color: rgb(0, 0, 0);\">IoT&nbsp;Architecture&nbsp;and&nbsp;Protocols</strong><span style=\"color: rgb(0, 0, 0);\">&nbsp;and&nbsp;</span><strong style=\"color: rgb(0, 0, 0);\">Security&nbsp;in&nbsp;IoT</strong><span style=\"color: rgb(0, 0, 0);\">.&nbsp;Students&nbsp;gain&nbsp;hands-on&nbsp;experience&nbsp;with&nbsp;IoT&nbsp;communication,&nbsp;protocols,&nbsp;and&nbsp;security-related&nbsp;concepts.</span></p>"
                },
                {
                  "name": "MTIO 207: Lab-IV (203)",
                  "description": "<p><span style=\"color: rgb(0, 0, 0);\">Provides&nbsp;practical&nbsp;exposure&nbsp;to&nbsp;</span><strong style=\"color: rgb(0, 0, 0);\">Wireless&nbsp;Sensor&nbsp;Networks</strong><span style=\"color: rgb(0, 0, 0);\">,&nbsp;focusing&nbsp;on&nbsp;the&nbsp;implementation&nbsp;and&nbsp;experimentation&nbsp;of&nbsp;concepts&nbsp;related&nbsp;to&nbsp;sensor&nbsp;nodes,&nbsp;wireless&nbsp;communication,&nbsp;and&nbsp;network&nbsp;organization.</span></p>"
                }
              ]
            }
          ]
        },
